// Convert Polygon2d to CGAL Polygon_2
auto convertToCGALPolygon = [](const Polygon2d& polygon) {
    internal::Polygon_2 cgalPolygon;
    for (const auto& point : polygon.vectorPoints()) {
        cgalPolygon.push_back(internal::Point_2(point.x(), point.y()));
    }
    return cgalPolygon;
};

// Convert CGAL Polygon_with_holes_2 to PolygonWithHoles2d
auto convertToPolygonWithHoles = [](const internal::Polygon_with_holes_2& pwh) {
    PolygonWithHoles2d result;

    // Extract outer boundary
    std::vector<Point2d> outerBoundary;
    for (auto it = pwh.outer_boundary().vertices_begin(); it != pwh.outer_boundary().vertices_end(); ++it) {
        double x, y;
        internal::getCoordinates(*it, x, y);
        outerBoundary.emplace_back(x, y);
    }
    result.outerBoundary = outerBoundary;

    // Extract holes
    for (auto hit = pwh.holes_begin(); hit != pwh.holes_end(); ++hit) {
        std::vector<Point2d> hole;
        for (auto vit = hit->vertices_begin(); vit != hit->vertices_end(); ++vit) {
            double x, y;
            internal::getCoordinates(*vit, x, y);
            hole.emplace_back(x, y);
        }
        result.holes.push_back(hole);
    }

    return result;
};

// Convert input polygons to CGAL polygons
internal::Polygon_2 cgalP1 = convertToCGALPolygon(P1);
internal::Polygon_2 cgalP2 = convertToCGALPolygon(P2);

// Perform union operation
internal::Pwh_list_2 unionResult;
CGAL::join(cgalP1, cgalP2, std::back_inserter(unionResult));

// Convert result back to our format
std::vector<PolygonWithHoles2d> result;
for (const auto& pwh : unionResult) {
    result.push_back(convertToPolygonWithHoles(pwh));
}

